import numpy as np
np.random.seed(42)

# ============================================================
# GENERATION QUALITY EVALUATION
# Reuses model components defined in previous blocks
# ============================================================

# --- Compact model rebuild + training ---
class CT:
    def __init__(self,text):
        ch=sorted(set(text));self.c2i={c:i for i,c in enumerate(ch)};self.i2c={i:c for i,c in enumerate(ch)};self.V=len(ch)
    def encode(self,t):return[self.c2i.get(c,0)for c in t]
    def decode(self,ids):return''.join(self.i2c.get(i,'?')for i in ids)
class LN:
    def __init__(self,d):self.g=np.ones(d);self.b=np.zeros(d)
    def forward(self,x):mu=x.mean(-1,keepdims=True);v=x.var(-1,keepdims=True);return self.g*((x-mu)/np.sqrt(v+1e-5))+self.b
class At:
    def __init__(self,d,h,s):
        self.h=h;self.hd=d//h;self.Wq=np.random.randn(d,d)*s;self.Wk=np.random.randn(d,d)*s
        self.Wv=np.random.randn(d,d)*s;self.Wo=np.random.randn(d,d)*s
    def forward(self,x):
        B,T,C=x.shape;h=self.h;hd=self.hd
        Q=(x@self.Wq).reshape(B,T,h,hd).transpose(0,2,1,3);K=(x@self.Wk).reshape(B,T,h,hd).transpose(0,2,1,3)
        V=(x@self.Wv).reshape(B,T,h,hd).transpose(0,2,1,3);sc=Q@K.transpose(0,1,3,2)/np.sqrt(hd)
        sc+=np.triu(np.ones((T,T)),k=1)*(-1e9);e=np.exp(sc-sc.max(-1,keepdims=True));a=e/e.sum(-1,keepdims=True)
        return(a@V).transpose(0,2,1,3).reshape(B,T,C)@self.Wo
class FF:
    def __init__(self,d,s):
        df=4*d;self.W1=np.random.randn(d,df)*s;self.b1=np.zeros(df);self.W2=np.random.randn(df,d)*s;self.b2=np.zeros(d)
    def forward(self,x):z=x@self.W1+self.b1;return(0.5*z*(1+np.tanh(np.sqrt(2/np.pi)*(z+0.044715*z**3))))@self.W2+self.b2
class Bk:
    def __init__(self,d,h,s):self.ln1=LN(d);self.at=At(d,h,s);self.ln2=LN(d);self.ff=FF(d,s)
    def forward(self,x):x=x+self.at.forward(self.ln1.forward(x));x=x+self.ff.forward(self.ln2.forward(x));return x
class GPT:
    def __init__(self,V,d,h,L,T):
        s=0.02;rs=s/np.sqrt(2*L);self.tok=np.random.randn(V,d)*s;self.pos=np.random.randn(T,d)*s
        self.blocks=[Bk(d,h,rs)for _ in range(L)];self.ln_f=LN(d);self.head=np.random.randn(d,V)*s;self.V=V;self.T=T
    def forward(self,ids):
        B,T=ids.shape;x=self.tok[ids]+self.pos[:T]
        for bl in self.blocks:x=bl.forward(x)
        return self.ln_f.forward(x)@self.head

corpus="the cat sat on the mat.\\nthe dog ran in the park.\\nthe model learns to predict.\\nattention helps focus on context.\\ntraining requires data and loss.\\neach layer transforms input.\\npretraining teaches understanding.\\n"*6
tk=CT(corpus);ids_all=tk.encode(corpus);T=32;data=[]
for i in range(0,len(ids_all)-T,10):
    ch=ids_all[i:i+T+1]
    if len(ch)==T+1:data.append((np.array(ch[:-1]),np.array(ch[1:])))
model=GPT(tk.V,64,4,4,T)
for step in range(80):
    idx=np.random.choice(len(data),6);inp=np.stack([data[i][0]for i in idx]);tgt=np.stack([data[i][1]for i in idx])
    lo=model.forward(inp);B,Tl,V=lo.shape;s=lo-lo.max(-1,keepdims=True);p=np.exp(s)/np.exp(s).sum(-1,keepdims=True)
    oh=np.zeros_like(p)
    for b in range(B):
        for t in range(Tl):oh[b,t,tgt[b,t]]=1.0
    dl=(p-oh)/(B*Tl);x=model.tok[inp]+model.pos[:Tl]
    for bl in model.blocks:x=bl.forward(x)
    x=model.ln_f.forward(x);dh=np.zeros_like(model.head)
    for b in range(B):dh+=x[b].T@dl[b]
    gn=np.sqrt((dh**2).sum())
    if gn>1:dh/=gn
    lr=0.004 if step<15 else 0.002*(1+np.cos(np.pi*(step-15)/65))/2
    model.head-=lr*dh;de=np.zeros_like(model.tok);dx=dl@model.head.T
    for b in range(B):
        for t in range(Tl):de[inp[b,t]]+=dx[b,t]
    en=np.sqrt((de**2).sum())
    if en>1:de/=en
    model.tok-=lr*de

def gen(prompt,n=80,temp=0.7,strat='temp',k=10,p_th=0.9):
    ids=tk.encode(prompt)
    for _ in range(n):
        ctx=np.array([ids[-T:]]);lo=model.forward(ctx)[0,-1]
        if strat=='greedy':nxt=int(np.argmax(lo))
        elif strat=='temp':
            sc=lo/temp;pr=np.exp(sc-sc.max());pr/=pr.sum();nxt=int(np.random.choice(len(pr),p=pr))
        elif strat=='top_k':
            sc=lo/temp;ti=np.argsort(sc)[-k:];f=np.full_like(sc,-1e9);f[ti]=sc[ti]
            pr=np.exp(f-f.max());pr/=pr.sum();nxt=int(np.random.choice(len(pr),p=pr))
        elif strat=='top_p':
            sc=lo/temp;pr=np.exp(sc-sc.max());pr/=pr.sum();si=np.argsort(pr)[::-1]
            cs=np.cumsum(pr[si]);cut=np.searchsorted(cs,p_th)+1;ni=si[:cut];np_=pr[ni];np_/=np_.sum()
            nxt=int(np.random.choice(ni,p=np_))
        ids.append(nxt)
    return tk.decode(ids[len(tk.encode(prompt)):])

ppl_total=0.0
for i in range(min(20,len(data))):
    inp,tgt=data[i];lo=model.forward(inp.reshape(1,-1))[0]
    s=lo-lo.max(-1,keepdims=True);lp=s-np.log(np.exp(s).sum(-1,keepdims=True))
    ppl_total-=lp[np.arange(T),tgt].mean()
ppl=float(np.exp(ppl_total/min(20,len(data))))

print("="*58)
print("  GENERATION QUALITY EVALUATION")
print("="*58)
print(f"\\n  1. PERPLEXITY: {ppl:.1f} (random: {tk.V})")
if ppl<tk.V:print(f"     {(1-ppl/tk.V)*100:.0f}% better than random!")
print(f"\\n  2. STRATEGY COMPARISON")
print(f"     {'Strategy':<14} {'Div-1':>7} {'Div-2':>7} {'3g-Rep':>7}")
print("     "+"-"*38)
for name,strat in[('Greedy','greedy'),('Temp 0.7','temp'),('Top-k 10','top_k'),('Top-p 0.9','top_p')]:
    d1s,d2s,rs=[],[],[]
    for _ in range(5):
        t=gen("the ",80,0.7,strat)
        d1=len(set(t))/max(1,len(t));bg=[t[i:i+2]for i in range(len(t)-1)];d2=len(set(bg))/max(1,len(bg))
        ng=[t[i:i+3]for i in range(len(t)-2)];r=1-len(set(ng))/max(1,len(ng))
        d1s.append(d1);d2s.append(d2);rs.append(r)
    print(f"     {name:<14} {np.mean(d1s):>5.3f}   {np.mean(d2s):>5.3f}   {np.mean(rs):>5.3f}")
print(f"\\n  3. SAMPLE OUTPUTS")
for name,strat in[('Greedy','greedy'),('Temp','temp'),('Top-k','top_k'),('Top-p','top_p')]:
    t=gen("the ",50,0.7,strat)
    print(f"     {name:<7} 'the {t[:48].replace(chr(10),chr(32))}'")
